// Applied rules: [III④]
// Skipped rules: [C3: The only concrete C3 hit is a per-iteration source-byte load inside the same raw-pointer copy loop. There is no loop-invariant field/value read to hoist (S2 has no leverage), and S1 signature lift would require caller-wide proof for a low-level memcpy-like routine where overlap semantics must be checked separately. III④ body-local slice conversion subsumes the concrete raw access sites [1,2] that induce the aliasing gap, so no standalone C3 rewrite is planned.]
unsafe fn lodepng_memcpy(
    mut dst: *mut c_void,
    mut src: *const c_void,
    mut size: size_t,
) {
    // SAFETY: `size` is the explicit L1 length parameter for this copy region; callers of
    // this unsafe function must provide `src` as non-null and valid for reads of `size`
    // bytes, and `dst` as non-null and valid for writes of `size` bytes. This body-local
    // reborrow creates shared/mutable slice views only for the duration of this function.
    // As a memcpy-like routine, callers must also uphold the non-aliasing requirement for
    // these slice references over the rewrite region.
    let src = unsafe { core::slice::from_raw_parts(src as *const u8, size as usize) };
    // SAFETY: `size` is the explicit L1 length parameter for this copy region; callers of
    // this unsafe function must provide `dst` as non-null and valid for writes of `size`
    // bytes. The mutable slice is confined to this function body, and callers must uphold
    // that no other live references alias this region during the copy.
    let dst = unsafe { core::slice::from_raw_parts_mut(dst as *mut u8, size as usize) };

    dst.copy_from_slice(src);
}

